from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    markers = [v for v, n in counts.items() if v != bg]
    if not markers:
        return [row[:] for row in grid]
    marker = max(markers, key=lambda v: counts[v])
    out = [row[:] for row in grid]
    # Color background cells lying strictly between successive markers on a row or column.
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v == marker]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 3
    return out
